import timefrom Sengo1 import *from mpython import *from machine import UARTuart1 = UART(1, baudrate=115200, tx=Pin.P14, rx=Pin.P13)sengo1 = Sengo1(0x60)brightness=9# 自定义函数def UART():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, index  sengo1.begin(uart1)def I2C():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, index  sengo1.begin(i2c)def Display():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, index  oled.fill_rect(0, (2-1)*16, 128, 16, 0)  oled.show()  # Sengo1不主动返回检测识别结果，需要主控板发送指令进行读取。读取的流程：首先读取识别结果的数量，接收到指令后，Sengo1会刷新结果数据，如果结果数量不为零，那么主控再发送指令读取结果的相关信息。请务必按此流程构建程序。  # Sengo最多输出1个识别结果。  if ((sengo1.GetValue(sengo1_vision_e.kVisionQrCode, sentry_obj_info_e.kStatus)) > 0):    # 当与二维码的距离在一定范围内，才输出识别结果    if ((sengo1.GetValue(sengo1_vision_e.kVisionQrCode,sentry_obj_info_e.kHeightValue)) > 40):      if ((sengo1.GetQrCodeString()).find("green")!=-1):        rgb[1] = (51*brightness//9, 204*brightness//9, 0*brightness//9)        rgb.write()      if ((sengo1.GetQrCodeString()).find("red")!=-1):        rgb[1] = (204*brightness//9, 0*brightness//9, 0*brightness//9)        rgb.write()      oled.DispChar((sengo1.GetQrCodeString()), 0, (2-1)*16, 1)      oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionQrCode,sentry_obj_info_e.kXValue)))), 32, 32, 1)      oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionQrCode,sentry_obj_info_e.kYValue)))), 96, 32, 1)      oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionQrCode,sentry_obj_info_e.kWidthValue)))), 32, 48, 1)      oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionQrCode,sentry_obj_info_e.kHeightValue)))), 96, 48, 1)  else:    oled.fill_rect(32,32,32,16,0)    oled.fill_rect(96,32,32,16,0)    oled.fill_rect(32,48,32,16,0)    oled.fill_rect(96,48,32,16,0)  oled.show()  time.sleep(0.1)  rgb[1] = (0*brightness//9, 0*brightness//9, 0*brightness//9)  rgb.write()# 等待Sengo1完成初始化，此延时不可以去掉，避免Sengo1初始化尚未完成，主控板已经发送指令time.sleep(2)oled.DispChar("Algo: QrCode", 0, 0, 1)oled.DispChar("x=", 0, 32, 1)oled.DispChar("y=", 64, 32, 1)oled.DispChar("w=", 0, 48, 1)oled.DispChar("h=", 64, 48, 1)oled.show()I2C()# 1、Sengo1可以检测并解码一个由不超过10个字符所生成的二维码；# 2、二维码的常见应用：门禁系统# 参考应用视频# https://www.bilibili.com/video/BV1ok4y157jV/?spm_id_from=333.1387.upload.video_card.click&vd_source=a6a4a13d17ed26ee248472534a8ec3cc# 3、Sengo1每次只能运行一种识别算法；# 4、正常使用时，应由主控板通过指令控制Sengo1算法的开启与关闭，而不是通过Sengo1的按键进行操作；sengo1.VisionBegin(sengo1_vision_e.kVisionQrCode)while True:  Display()